    static class IO extends PrintWriter {
        private InputStreamReader inStream;
        private static final int BUF_SIZE = 1 << 15;
        private char[] buf;
        private int pos;
        private int size;
        private StringBuilder sb;

        public IO() {
            super(new BufferedOutputStream(System.out));
            inStream = new InputStreamReader(System.in);
            buf = new char[BUF_SIZE];
            pos = 0;
            size = 0;
            sb = new StringBuilder();
        }

        private void fillBuffer() throws IOException {
            size = inStream.read(buf, 0, BUF_SIZE);
            pos = 0;
        }

        private boolean hasNextChar() throws IOException {
            if (pos >= size) {
                fillBuffer();
            }
            return size > 0;
        }

        private boolean isSpaceChar(char c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        private void skipSpaces() throws IOException {
            while (true) {
                if (!hasNextChar()) break;
                if (!isSpaceChar(buf[pos])) break;
                pos++;
            }
        }

        public String next() {
            try {
                sb.setLength(0);
                skipSpaces();
                int startIdx = pos;
                while (true) {
                    if (!hasNextChar()) break;
                    if (isSpaceChar(buf[pos])) break;
                    pos++;
                }
                sb.append(buf, startIdx, pos - startIdx);
                return sb.toString();
            } catch (IOException e) {
                throw new RuntimeException("IO.next: IOException");
            }
        }

        public long nextLong() {
            try {
                long res = 0;
                boolean positive = true;
                skipSpaces();
                if (buf[pos] == '-') {
                    positive = false;
                    pos++;
                }
                while (true) {
                    if (!hasNextChar()) break;
                    if (isSpaceChar(buf[pos])) break;
                    res = res * 10 + (buf[pos] - '0');
                    pos++;
                }
                return positive ? res : -res;
            } catch (IOException e) {
                throw new RuntimeException("IO.nextLong: IOException");
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }
